class FoodForLifeCountDownWidgetHandler extends elementorModules.frontend.handlers.Base{getDefaultSettings(){return{selectors:{container:".foodforlife-countdown"}}}getDefaultElements(){const e=this.getSettings("selectors");return{$container:this.$element.find(e.container)}}getCountDownInit(){jQuery(document.body).trigger("foodforlife_countdown",this.elements.$container)}onInit(){super.onInit();this.getCountDownInit()}}jQuery(window).on("elementor/frontend/init",()=>{elementorFrontend.hooks.addAction("frontend/element_ready/foodforlife-countdown.default",e=>{elementorFrontend.elementsHandler.addHandler(FoodForLifeCountDownWidgetHandler,{$element:e})});elementorFrontend.hooks.addAction("frontend/element_ready/foodforlife-banner.default",e=>{elementorFrontend.elementsHandler.addHandler(FoodForLifeCountDownWidgetHandler,{$element:e})});elementorFrontend.hooks.addAction("frontend/element_ready/foodforlife-product-deals.default",e=>{elementorFrontend.elementsHandler.addHandler(FoodForLifeCountDownWidgetHandler,{$element:e})})});